{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '멍한 느낌이 무엇을 덮고 있냐'고 질문한 것에 대해, 내담자가 반복된 무력감 끝에 형성한 '남들만큼 해낼 수 없는 사람'이라는 핵심 신념이 멍함 아래에 깔려 있는 정서적 토대가 될 수 있음. 형과의 비교 경험에서 비롯된 이 신념이 '좋은 건 아닌데 편한' 멍함으로 덮여 있을 가능성과 연결."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "'실패' 스키마가 멍함이라는 정서적 마비로 덮여 있을 수 있음. 상담사가 '덮고 있다'고 표현한 것은 스키마가 활성화될 때의 고통을 회피하기 위해 정서적 둔마가 작동하는 구조와 맞닿아 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/3"],
      "relevance": "'최선을 다해 도전했는데도 실패하면 무능함이 완전히 증명된다'는 두려움이 멍함으로 덮여 있는 핵심 감정일 수 있음. 상황 사례 3에서 '3년을 했는데 이 모양이면 머리 자체가 안 되는 거야'라는 자동사고가 바로 이 두려움이 덮여 있다가 스치는 순간을 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/3"],
      "relevance": "'제대로 안 해서 떨어진 것'이라고 여길 수 있으면 덜 비참할 것이라는 보호적 논리가 멍함을 '편하게' 만드는 기능적 이유를 설명함. 내담자가 '편한 쪽에 가깝다'고 한 것에 대해, 이 가정의 보호 기능이 작동하고 있음을 상담사가 탐색하려는 질문과 연결."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 직접 묘사한 '책상에 앉아도 손에 안 잡히고 휴대폰 보다가 새벽에 자는' 패턴이 이 대처 전략과 정확히 일치함. 상담사의 질문은 이 행동 패턴 아래에 어떤 감정이 덮여 있는지를 탐색하는 것이므로, 행동과 그 기능을 연결하는 이 전략이 관련됨."
    }
  ]
}

